<script setup>
import {ref,watch,computed,onUnmounted,nextTick} from 'vue';import {Head,useForm,usePage,router,Link} from '@inertiajs/vue3';import axios from 'axios';import RoundBuilder from '../Components/RoundBuilder.vue';import Errors from '../Components/Errors.vue';import Feedback from '../Components/Feedback.vue';import {art,message} from '../art';
const props=defineProps({catalog:Object,exams:Object,students:Array,presets:Array}),page=usePage();
const form=useForm({title:'SUSHI Comprehensive Exam',mode:'tutor',count:40,subjects:[...props.catalog.subjects],topics:[],topic_scope:'all',difficulty:'All',pool:'all',seed:Math.floor(Math.random()*4294967296),balance:true,allocation:{},minutes:30});
const draft=ref(null),busy=ref(false),error=ref(''),preset=ref(''),presetName=ref(''),presetOpen=ref(false),builderKey=ref(0);
const assigning=ref(null),assignment=useForm({students:[],opens_at:'',closes_at:'',minutes:60,max_attempts:1,release_answers:false});
function assign(){assignment.transform(d=>({...d,opens_at:new Date(d.opens_at).toISOString(),closes_at:new Date(d.closes_at).toISOString()})).post('/admin/exams/'+assigning.value+'/assign',{preserveScroll:true,onSuccess:()=>assigning.value=null})}
async function preview(){busy.value=true;error.value='';try{draft.value=(await axios.post('/exams/preview',form.data())).data}catch(e){error.value=message(e)}finally{busy.value=false}}
async function replace(position){busy.value=true;error.value='';try{draft.value=(await axios.post('/exam-drafts/'+draft.value.id+'/replace',{position,revision:draft.value.revision})).data}catch(e){error.value=message(e)}finally{busy.value=false}}
function save(){busy.value=true;router.post('/exam-drafts/'+draft.value.id+'/save',{revision:draft.value.revision},{preserveScroll:true,onSuccess:()=>draft.value=null,onError:e=>error.value=Object.values(e).join(' '),onFinish:()=>busy.value=false})}
async function duplicate(exam){busy.value=true;error.value='';try{draft.value=(await axios.post('/exams/'+exam.id+'/duplicate')).data;Object.assign(form,draft.value.settings,{title:draft.value.title});document.getElementById('bento-workbench')?.scrollIntoView({behavior:'smooth'})}catch(e){error.value=message(e)}finally{busy.value=false}}
function loadPreset(){const s=props.presets.find(p=>String(p.id)===preset.value)?.settings;if(s){Object.assign(form,s);form.seed=Math.floor(Math.random()*4294967296);builderKey.value++}}
function savePreset(){router.post('/exams/presets',{...form.data(),name:presetName.value},{preserveScroll:true,onSuccess:()=>{presetOpen.value=false;presetName.value=''}})}
watch(draft,(value,old)=>{if(value&&!old)nextTick(()=>document.getElementById('bento-workbench')?.scrollIntoView({block:'start'}))});
const blueprint=computed(()=>draft.value?.items.reduce((m,q)=>({...m,[q.subject]:(m[q.subject]||0)+1}),{})||{});
let poll;watch(()=>props.exams.data.some(e=>e.exports.some(x=>['queued','building','pending','processing'].includes(x.status))),pending=>{clearInterval(poll);if(pending)poll=setInterval(()=>{if(!document.hidden)router.reload({only:['exams'],preserveScroll:true})},4000)},{immediate:true});
onUnmounted(()=>clearInterval(poll));
</script>
<template><Head title="Bento Builder"/><div class="page-title"><div><p class="eyebrow">Pack an exam worth sharing</p><h1>Bento Builder</h1><p>Choose coverage, review every question, then serve your PDFs.</p></div><img class="portrait" :src="art.chef" alt="Bento Chef"></div>
<section id="bento-workbench" class="panel"><p v-if="error" class="notice error" role="alert">{{error}}</p><Errors :errors="form.errors"/>
<template v-if="!draft"><label>Exam title<input v-model="form.title" required maxlength="150"></label>
<div class="preset-row"><label v-if="presets.length">Saved recipes<select v-model="preset" @change="loadPreset"><option value="">Choose a preset</option><option v-for="p in presets" :key="p.id" :value="String(p.id)">{{p.name}}</option></select></label><button @click="presetOpen=!presetOpen">Save this recipe</button></div>
<div v-if="presetOpen" class="inset"><label>Preset name<input v-model="presetName" maxlength="80"></label><button :disabled="!presetName.trim()" @click="savePreset">Save preset</button></div>
<RoundBuilder :key="builderKey" :form="form" :catalog="catalog" bento :busy="busy" submit-label="Preview questions" @start="preview"/></template>
<template v-else><div class="row"><div><p class="eyebrow">Final tasting</p><h2>{{draft.title}}</h2><p>{{draft.items.length}} questions. Replace keeps the same subject and filters.</p></div><button :disabled="busy" @click="draft=null;builderKey++">Edit recipe</button></div>
<div class="chips"><span v-for="(n,s) in blueprint" :key="s" class="button">{{s}} · {{n}}</span></div>
<div class="exam-preview"><article v-for="(q,i) in draft.items" :key="i+'-'+q.id"><div class="row"><strong>{{i+1}}. {{q.id}} · {{q.subject}}</strong><button :disabled="busy" @click="replace(i)">Replace question {{i+1}}</button></div><p class="pre">{{q.stem}}</p><details><summary>Review choices and answer</summary><p v-for="(o,n) in q.options" :key="n">{{String.fromCharCode(65+n)}}. {{o}}</p><Feedback :question="q"/></details></article></div>
<div class="builder-actions"><p class="muted">Saving freezes this reviewed set.</p><button class="primary" :disabled="busy" @click="save">Save this bento</button></div></template></section>
<h2>Saved exam bentos</h2><p class="muted">PDF status updates automatically while this page is open.</p>
<article v-for="exam in exams.data" :key="exam.id" class="panel"><div class="row"><div><h2>{{exam.title}}</h2><p>{{exam.code}} · {{exam.items_count}} questions</p></div><button :disabled="busy" @click="duplicate(exam)">Duplicate as new exam</button></div>
<div class="row spaced"><div class="segmented"><button class="primary" @click="router.post('/exams/'+exam.id+'/export',{explanations:true},{preserveScroll:true})">Prepare PDF set</button><button @click="router.post('/exams/'+exam.id+'/export',{explanations:false},{preserveScroll:true})">Compact answer key</button></div><button v-if="page.props.user.role==='admin'" @click="assigning=assigning===exam.id?null:exam.id">Assign to learners</button></div>
<div v-for="ex in exam.exports" :key="ex.id" class="export-row" aria-live="polite"><span>Set {{ex.id}} · {{ex.status==='ready'?'Ready to download':ex.status}} {{ex.explanations?'· with explanations':''}}</span><div v-if="ex.status==='ready'" class="export-links"><a class="button" :href="'/exports/'+ex.id+'/paper'">Exam paper PDF</a><a class="button" :href="'/exports/'+ex.id+'/sheet'">Answer sheet PDF</a><a class="button" :href="'/exports/'+ex.id+'/key'">Answer key PDF</a></div><span v-if="ex.error" class="error">{{ex.error}}</span></div>
<form v-if="assigning===exam.id" class="inset assignment-panel" @submit.prevent="assign"><h3>Assign this saved exam</h3><p>This step schedules the exam for selected learners.</p><div class="form-grid"><label v-for="student in students" :key="student.id" class="check"><input type="checkbox" v-model="assignment.students" :value="student.id">{{student.username}}</label><label>Opens (your local time)<input v-model="assignment.opens_at" type="datetime-local" required></label><label>Closes (your local time)<input v-model="assignment.closes_at" type="datetime-local" required></label><label>Minutes per attempt<input v-model.number="assignment.minutes" type="number" min="1" max="360"></label><label>Attempt limit<input v-model.number="assignment.max_attempts" type="number" min="1" max="20"></label><label class="check"><input v-model="assignment.release_answers" type="checkbox">Release explanations after submission</label></div><Errors :errors="assignment.errors"/><button class="primary" :disabled="assignment.processing">Save assignment</button></form></article>
<p v-if="!exams.data.length" class="panel">Your saved bentos will appear here.</p><div class="row"><Link v-if="exams.prev_page_url" :href="exams.prev_page_url" preserve-state preserve-scroll>Previous</Link><Link v-if="exams.next_page_url" :href="exams.next_page_url" preserve-state preserve-scroll>Next</Link></div></template>
